def sm(z):
 z=z-z.max(-1,keepdims=True);p=np.exp(z);return p/p.sum(-1,keepdims=True)
def calc(X,Y,L,grad=True):
 E,A,pi=[sm(z) for z in L];N,T=X.shape;K=len(pi);b=np.tile(pi,(N,1));cache=[];loss=0
 for t in range(T):
  p=b@E;loss+=np.sum(Y[:,t]*np.log(np.maximum(Y[:,t],1e-20)/np.maximum(p,1e-20)))
  e=E[:,X[:,t]].T;r=b*e;norm=r.sum(1,keepdims=True);r/=norm
  if grad:cache.append((b,p,e,r,norm))
  b=r@A
 if not grad:return loss/(N*T)
 dE=np.zeros_like(E);dA=np.zeros_like(A);db=np.zeros_like(b)
 for t in range(T-1,-1,-1):
  b,p,e,r,norm=cache[t]
  dA+=r.T@db;dr=db@A.T;du=(dr-(dr*r).sum(1,keepdims=True))/norm
  de=du*b; db=du*e
  for a in range(16):dE[:,a]+=de[X[:,t]==a].sum(0)
  dp=-Y[:,t]/np.maximum(p,1e-20);dE+=b.T@dp;db+=dp@E.T
 dpi=db.sum(0);grads=[]
 for param,g in zip((E,A,pi),(dE,dA,dpi)):
  grads.append(param*(g-(g*param).sum(-1,keepdims=True))/(N*T))
 return loss/(N*T),grads
def fit(X,Y,E,A,pi,steps=1000,rate=.04,val=None,verbose=False):
 L=[np.log(np.maximum(z,1e-7)) for z in (E,A,pi)];m=[np.zeros_like(z) for z in L];v=[np.zeros_like(z) for z in L];best=(1e10,None,0)
 for it in range(1,steps+1):
  loss,g=calc(X,Y,L)
  for k in range(3):
   m[k]=.9*m[k]+.1*g[k];v[k]=.999*v[k]+.001*g[k]*g[k];L[k]-=rate*(m[k]/(1-.9**it))/(np.sqrt(v[k]/(1-.999**it))+1e-8)
  if it%100==0 or it==steps:
   vl=calc(*val,L,grad=False) if val is not None else loss
   if vl<best[0]:best=(vl,[z.copy() for z in L],it)
   if verbose:print(it,loss,vl,flush=True)
 return [sm(z) for z in best[1]],best[0],best[2]
''')
